from openai import OpenAI
import re

client = OpenAI()
TOOLS = {"calc": lambda x: str(eval(x))}

SYSTEM = ("Use format: Thought: ...\nAction: tool[args]\nObservation: ...\n"
          "When done: Final: answer")

def react(question: str):
    msgs = [{"role": "system", "content": SYSTEM}, {"role": "user", "content": question}]
    for _ in range({{max_steps}}):
        r = client.chat.completions.create(model="{{model_name}}", messages=msgs, stop=["Observation:"])
        text = r.choices[0].message.content
        if "Final:" in text:
            return text.split("Final:")[-1].strip()
        m = re.search(r"Action: (\w+)\[(.+?)\]", text)
        if not m:
            return text
        obs = TOOLS[m.group(1)](m.group(2))
        msgs.append({"role": "assistant", "content": text})
        msgs.append({"role": "user", "content": f"Observation: {obs}"})
    return "max steps"
